CREATE TABLE `products` (
  `id` varchar(128) NOT NULL,
  `slug` varchar(160) NOT NULL,
  `name` varchar(255) NOT NULL,
  `category` varchar(120) NOT NULL,
  `price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `description` text NOT NULL,
  `has_upload` tinyint(1) NOT NULL DEFAULT '0',
  `requires_quote` tinyint(1) NOT NULL DEFAULT '0',
  `min_qty` int NOT NULL DEFAULT '1',
  `track_inventory` tinyint(1) NOT NULL DEFAULT '0',
  `stock_quantity` int unsigned NOT NULL DEFAULT '0',
  `image` varchar(2048) NOT NULL DEFAULT '',
  `options_json` json NOT NULL,
  `addons_json` json NOT NULL,
  `featured` tinyint(1) NOT NULL DEFAULT '0',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `images_json` text,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_products_active_category` (`active`,`category`),
  KEY `idx_products_featured` (`featured`,`active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
