INSERT INTO `products` VALUES ('12-oz-rock','12-oz-rock','12 oz. Rock','CandleArt',16.00,'Each CandleArt jar kit Includes colored granulated wax, 2 wicks (for use for havdala), spoon for layering wax, skewer for designing and wax to melt for sealing the candle.\r\\n\r\\nSimilar to a sandart craft, using granulated wax instead of sand, to create your CandleArt in a jar.\r\\n\r\\nInstructions: Using a small spoon, slowly add wax to jar. When bottom layer is covered, insert wicks into center of jar. (They will become set in place as more wax is added.) Continue filling up the jar, leaving about 1/2 inch on the top. You could use a skewer to make designs.  Spoon melted wax over candle to set. Trim wicks to size. Enjoy!\r\\n\r\\n<span style=\"font-weight: 400;\"> </span>\r\\n\r\\n<img class=\"alignnone size-medium wp-image-1972\" src=\"https://dandicraft.com/wp-content/uploads/2025/11/freepik_br_7e5b9e80-2e7c-4571-9c3f-f28bd319dd9d-300x120.png\" alt=\"\" width=\"300\" height=\"120\" />',0,0,1,0,0,'https://pink-dugong-468121.hostingersite.com/wp-content/uploads/2025/11/12-jar.png','[]','[]',0,1,'2026-09-25 20:02:42','2026-09-25 20:02:42','[\"https://pink-dugong-468121.hostingersite.com/wp-content/uploads/2025/11/12-jar.png\"]'),('16-bulldog','16-bulldog','16” Bulldog','Stuff-a-Bear',0.00,'<p data-start=\"1346\" data-end=\"1430\">Perfect for parties, gifts, schools, and camps — or just a creative family activity!</p>',0,0,1,0,0,'https://pink-dugong-468121.hostingersite.com/wp-content/uploads/2025/11/Bulldog.png','[]','[]',0,1,'2026-09-25 20:02:42','2026-09-25 20:02:42','[\"https://pink-dugong-468121.hostingersite.com/wp-content/uploads/2025/11/Bulldog.png\"]'),('16-bulldog-basic-tee','16-bulldog-basic-tee','16” Bulldog - Basic Tee','Uncategorized',20.00,'',0,0,1,0,0,'https://pink-dugong-468121.hostingersite.com/wp-content/uploads/2025/11/Bulldog.png','[]','[]',0,1,'2026-09-25 20:02:42','2026-09-29 16:42:54','[]'),('16-bulldog-black-tee','16-bulldog-black-tee','16” Bulldog 